const targeting = createTargetingController({
  world,
  messageLog,
  playerEntity: () => playerEntity(world),
  dispatchRules: (action) => _sharedRulesDispatcher(action),
  isVisibleAt: (x, y) => isVisibleAt(x, y),
});
targeting.installKeyboardHandlers();
addEventListener('ui:openRangedPointTargeting', (ev) => {
  if (targeting.isActive()) return;
  const detail = /** @type {CustomEvent} */ (ev).detail || {};
  targeting.openRangedPointTargeting({
    actorId: Number(detail.actorId || 0) | 0,
    itemId: Number(detail.itemId || 0) | 0,
    itemName: String(detail.itemName || 'ranged weapon'),
    range: Math.max(1, Number(detail.range || 1) | 0),
    isBow: detail.isBow === true,
  });
});

// ---- Extracted wiring modules -----------------------------------------------
installScrollWandWiring({ world, targeting, playerEntity: () => playerEntity(world) });
const requestItemAbility = createContentAbilityController({ world, targeting, playerEntity: () => playerEntity(world), scanVisibleEnemies });
installPetWiring({ world, playerEntity: () => playerEntity(world) });
installLodbrokSpawnWiring(world);

function buildQuickItemPinDetailFromWorld(itemId) {
  const id = Number(itemId || 0) | 0;
  const identity = String(world.get(id, NamedIdentity)?.identity || '');
  return {
    itemId: id,
    identity,
    pinKey: identity || (id > 0 ? `id:${id}` : ''),
  };
}

function tryOpenItemChannelTargeter(itemId) {
  const id = Number(itemId || 0) | 0;
  if (!(id > 0)) return false;
  const identity = String(world.get(id, NamedIdentity)?.identity || '');
  const action = getUseAction(identity);
  if (!action?.targeting) return false;

  const pe = playerEntity(world);
  if (!pe?.id) return true;
  const cfg = action.targeting;
  const range = Math.max(1, Number(cfg.fallbackRange || 6) | 0);
  targeting.cancelAll();
  targeting.openSpellTargeting({
    spellName: cfg.name || identity,
    range,
    requiresLOS: cfg.requiresLOS === true,
    requiresVisible: cfg.requiresVisible === true,
    validateTarget: cfg.validateTarget,
    onConfirm(x, y) {
      if (typeof cfg.onConfirm === 'function') cfg.onConfirm(world, pe.id, id, x, y);
    },
  }, cfg.describePrompt ? cfg.describePrompt(range) : `Use ${cfg.name || identity} (range ${range}).`);
  return true;
}

// Keep quick-slot and pinned chips in sync when items are consumed.
world.on('item:used', ({ itemId }) => {
  const detail = buildQuickItemPinDetailFromWorld(itemId);
  try { window.dispatchEvent(new CustomEvent('ui:itemUsed', { detail })); } catch (e) { console.debug('[main] dispatch ui:itemUsed:', e); }
  try { window.dispatchEvent(new CustomEvent('ui:requestInventoryData')); } catch (e) { console.debug('[main] dispatch ui:requestInventoryData:', e); }
});

// Keep quick-slot and pinned chips in sync when items are thrown.
world.on('item:thrown', ({ itemId }) => {
  const detail = buildQuickItemPinDetailFromWorld(itemId);
  try { window.dispatchEvent(new CustomEvent('ui:itemThrown', { detail })); } catch (e) { console.debug('[main] dispatch ui:itemThrown:', e); }
  try { window.dispatchEvent(new CustomEvent('ui:requestInventoryData')); } catch (e) { console.debug('[main] dispatch ui:requestInventoryData:', e); }
});

function findScrollOfIdentifyInPlayerInventory(playerId) {
   * @param {string} opts.spellId
   * @param {string} opts.spellName
   * @param {number} opts.range
   * @param {Array<{id:number,x:number,y:number}>} opts.enemies
   * @param {((id:number)=>void)} [opts.onConfirm]
   */
  function openEnemyTargeting({ spellId, spellName, range, enemies, onConfirm }) {
    _enemy = {
      spellId,
      spellName,
      range,
      enemies,
      index: 0,
      onConfirm: onConfirm || null,
    };
    _cursor = enemies.length > 0 ? { x: enemies[0].x, y: enemies[0].y } : null;
    _spell = null;
    _throw = null;
    log(`Choose target for ${spellName}. Tab to cycle enemies, Enter to confirm, Esc to cancel.`);
  }

  function openRangedPointTargeting(opts) {
    _ranged = { ...opts };
    _spell = null;
    _throw = null;
    _enemy = null;
    const pe = playerEntity();
    if (pe) _cursor = { x: pe.pos.x | 0, y: pe.pos.y | 0 };
    log(`Choose a tile for ${bracketizeName(opts.itemName)}. Tap a tile to fire. Esc cancels.`);
  }

  /**
   * Open tile-targeted spell targeting.
   * @param {SpellTargeting} opts
   * @param {string} prompt  e.g. "Choose blink destination..."
   */
  function openSpellTargeting(opts, prompt) {
    _spell = { ...opts };
    _throw = null;
    _enemy = null;
    const pe = playerEntity();
    if (opts.candidateTargets?.length) {
      _cursor = { x: opts.candidateTargets[0].x | 0, y: opts.candidateTargets[0].y | 0 };
    } else if (pe) _cursor = { x: pe.pos.x | 0, y: pe.pos.y | 0 };
    log(prompt);
  }

  /**
   * Open throw targeting.
   * @param {ThrowTargeting} opts
   */
  function openThrowTargeting(opts) {
    _throw = { ...opts };
    _spell = null;
    _enemy = null;
    const pe = playerEntity();
    if (pe) _cursor = { x: pe.pos.x | 0, y: pe.pos.y | 0 };
    log(`Throw ${bracketizeName(opts.itemName)} where? Tap/click a tile or use arrow keys + Enter (up to ${opts.range}). Press Esc to cancel.`);
  }

  /**
   * Toggle spell targeting for a spell that's already active → cancel it.
   * Returns true if toggled off.
   */
  function toggleSpellOff(spellId) {
    if (_spell?.spellId === spellId) {
      log(`${_spell.spellName} targeting cancelled.`);
      _spell = null;
      _cursor = null;
      return true;
    }
    return false;
  }

  /**
   * Toggle enemy targeting for a spell that's already cycling → cancel it.
   * Returns true if toggled off.
   */
  function toggleEnemyOff(spellId) {
    if (_enemy?.spellId === spellId) {
      log(`${_enemy.spellName} targeting cancelled.`);
      _enemy = null;
      _cursor = null;
      return true;
    }
    return false;
  }

  // ── Keyboard handling ─────────────────────────────────────────────────────

  function _handleEscape(ev) {
    if (_enemy) {
      log(`${_enemy.spellName} targeting cancelled.`);
      _enemy = null;
      _cursor = null;
      ev.preventDefault();
      return true;
    }
    if (_spell) {
      log(`${_spell.spellName} targeting cancelled.`);
      _spell = null;
      _cursor = null;
      ev.preventDefault();
      return true;
    }
    if (_throw) {
      log(`${bracketizeName(_throw.itemName)} throw cancelled.`);
      _throw = null;
      _cursor = null;
      ev.preventDefault();
      return true;
    }
    if (_ranged) {
      log(`${bracketizeName(_ranged.itemName)} targeting cancelled.`);
      _ranged = null;
      _cursor = null;
      ev.preventDefault();
      return true;
    }
    return false;
  }

  function _handleEnemyKeys(ev) {
    if (!_enemy) return false;

