    ctx.cancel({ code: "USE_GATE_NO_ACTOR", message: "Actor is not alive." });
    return { metrics };
  }
  if (!ctx.query.alive(itemId)) {
    ctx.cancel({ code: "USE_GATE_NO_ITEM", message: "Item no longer exists." });
    return { metrics };
  }
